"""Круговая диаграмма с выдвинутым сектором."""


def draw(fig):
    names = ["Python", "C", "Lua", "Shell"]
    ax = fig.add_subplot()
    ax.pie([55, 20, 15, 10], labels=names, explode=(0.08, 0, 0, 0), autopct="%d%%", startangle=90)
    ax.set_title("Языки в проекте")


if __name__ == "__main__":
    from mpldemo import run
    run(draw)
